func validUsername(s string) bool {
	// Длина в ASCII-символах (байтах): от 3 до 16
	if len(s) < 3 || len(s) > 16 {
		return false
	}

	for i := 0; i < len(s); i++ {
		c := s[i]
		isLower := c >= 'a' && c <= 'z'
		isUpper := c >= 'A' && c <= 'Z'
		isDigit := c >= '0' && c <= '9'
		isUnderscore := c == '_'

		if !(isLower || isUpper || isDigit || isUnderscore) {
			return false
		}
	}
	return true
}
